import React, { useEffect, useRef } from "react";
import Matter from "matter-js";
import './spoondrop.css';
import { Link } from 'react-router-dom';
import { createPlusScore, getSpoon } from "./util/spoonHelper";

const SpoonSaberBattle = () => {
  const boxRef = useRef(null);
  const canvasRef = useRef(null);
  
  useEffect( () => {

    var isMobile = false;
    var width = window.innerWidth;
    var height = window.innerHeight;
    let Engine = Matter.Engine;
    let Render = Matter.Render;
    let Runner = Matter.Runner;
    let Bodies = Matter.Bodies;
    let Body = Matter.Body;
    let Composite = Matter.Composite;
    let Mouse = Matter.Mouse;
    let MouseConstraint = Matter.MouseConstraint;
  
    let engine = Engine.create({gravity: {y: 0}});
    let runner = Runner.create({});

    var render = Render.create({
      element: boxRef.current,
      engine: engine,
      canvas: canvasRef.current,
      options: {
        width: window.innerWidth,
        height: window.innerHeight+window.innerHeight,
        wireframes: false
      }
    });

    var gameWidth = width*4/5;
    var margin = (width-gameWidth)/2;
    var points = 0;
    var fric = 0.1
    var size = 100; //size var for spoon
    //mobile augmentations
    if(width < 800){
      fric = 0.03
      isMobile = true;
      size = 50;
    }

    // add mouse control
    var mouse = Mouse.create(render.canvas),
      mouseConstraint = MouseConstraint.create(engine, {
        mouse: mouse,
        constraint: {
          stiffness: 0.2,
          render: {
            visible: false
          }
        }
      });
    
    Composite.add(engine.world, mouseConstraint);

    //saber colors
    let yellow = "#ffff00",
      neonGreen = "#b4ff00",
      lime = "#46ff00",
      green = "#00FF00",
      mint = "#00ff3c",
      cyan = "#00ff8c",
      sky = "#008CFF",
      blue = "#0000FF",
      purple = "#7300ff",
      magenta = "#dc00FF";
    
    let red = "#ff2727ff",
      bloodOrange = "#ff3c00ff";
      
    const CATEGORY_SPOON = 0x0002;
    const CATEGORY_ENEMY_SPOON = 0x0004;

    const enemyFilter = {
      category: CATEGORY_ENEMY_SPOON,
      mask: CATEGORY_SPOON,
    };

    const spoonFilter = {
      category: CATEGORY_SPOON,
      mask: CATEGORY_ENEMY_SPOON,
    };
    
    //gamevars init
    var gameStarted = false;
    var resettable = false;
    var allMovements = [];
    var playerMovement;
    const spoonStart = {
      x: width/2,
      y: height/2
    }
    var force = 0.015;
    
    var saber = getSpoon(size, spoonStart.x, spoonStart.y, spoonFilter, neonGreen, "bottom")
    saber.frictionAir = fric;
    Composite.add(engine.world, saber);

    Matter.Events.on(mouseConstraint, "mousedown", function(event) {
      if(!gameStarted){startGame();}
      playerMovement = setInterval(function() {
        if(true){
          let mousePos = {x: mouse.position.x, y: mouse.position.y};
          let saberPos = {x: saber.position.x, y: saber.position.y};
          let stoppingDistance = 5;
          let inPositionX = Math.abs(Math.abs(mousePos.x) - Math.abs(saberPos.x)) < stoppingDistance;
          let inPositionY = Math.abs(Math.abs(mousePos.y) - Math.abs(saberPos.y)) < stoppingDistance;
          let directionalVector = {x: mousePos.x-saberPos.x, y: mousePos.y-saberPos.y};
          let magnitude = Math.sqrt(directionalVector.x ** 2 + directionalVector.y ** 2);
          let normalized = {x: directionalVector.x/magnitude, y: directionalVector.y/magnitude};
          if(!inPositionX){
            Matter.Body.applyForce(saber, saber.position, Matter.Vector.create((normalized.x)*force, 0));
            console.log("x force applied");
          }
          else{
            Body.setVelocity(saber, Matter.Vector.create(0, saber.velocity.y));
            console.log("inpositionX")
          }
          if(!inPositionY){
            Matter.Body.applyForce(saber, saber.position, Matter.Vector.create(0, (normalized.y)*force));
            console.log("y force applied");
          }
          else{
            Body.setVelocity(saber, Matter.Vector.create(saber.velocity.x, 0));
            console.log("inpositionY")
          }
          if(inPositionX && inPositionY){
            Body.setVelocity(saber, Matter.Vector.create(0, 0));
            console.log("force not applied")
          }
        }
      }, 10);
       allMovements.push(playerMovement);
    });

    Matter.Events.on(mouseConstraint, "mouseup", function(event){
      allMovements.forEach(element => {
        clearInterval(element);
      })
    });
    
    Matter.Events.on(engine, "collisionStart", function(event) {

    });

    
    
    function startGame() {
    }
    function restartGame(){
      if (resettable === true){
        //cleanup and reset
      }
    }
    function gameOver() {
      gameStarted = false;
      resettable = true;
      //set text
      //leaderboards
    }

    function doPointIncrement(spoon, cerealPos) {
      //points+= 10*(spoonState.cerealHits+1);
      //createPlusScore(cerealPos.x, cerealPos.y, spoonState.cerealHits*10)
    }

    function setText() {
      const dropperEl = document.getElementById("dropper");
      //point tracking messages
      if(points >= 2500){
        if (dropperEl) dropperEl.innerHTML = "Whoa! " + points + " points";
      }
      else if(points >= 1000){
        if (dropperEl) dropperEl.innerHTML = "Nice! " + points + " points"; 
      }
      else{
        if (dropperEl) dropperEl.innerHTML = points + " points";
      }
      //if (dropperEl && debug) dropperEl.innerHTML = "Whoa! " + points + " points. Speed = " + speed;
    }

    Runner.run(runner, engine)
    Render.run(render);
  // Cleanup on unmount
    return () => {
      Render.stop(render);
      Runner.stop(runner);
      Composite.clear(engine.world, false);
      Engine.clear(engine);
      render.canvas.remove();
      render.textures = {};
    };
  }, []);



  
    return (
      <div className="notscene">
      <canvas ref={canvasRef} />
      <Link to="/spoondropMenu"><button className='back-button' onClick={console.log("button pressed")}></button></Link>
      <div id="menutext">
        <p id="dropper">instructions</p>
        <p id="descenttut"className="droppertext">do it!</p>
      </div>
    </div>
  )
  
  
};

export default SpoonSaberBattle;
